namespace ConditionCoverage;

public static class ProbeSource
{
    public static string NameFor(string assembly)
        => "__CondCov_" + new string(assembly.Select(c => char.IsLetterOrDigit(c) ? c : '_').ToArray());

    /// <summary>Sinh class probe: đếm true/false theo id bằng Interlocked, ghi file khi process thoát.</summary>
    public static string Generate(string assembly, int count)
    {
        string name = NameFor(assembly);
        return $$"""
                 // <auto-generated> condition-coverage probe </auto-generated>
                 #nullable disable
                 internal static class {{name}}
                 {
                     private static readonly int[] t = new int[{{Math.Max(count, 1)}}];
                     private static readonly int[] f = new int[{{Math.Max(count, 1)}}];
                     private static int dumped;

                     static {{name}}()
                     {
                         global::System.AppDomain.CurrentDomain.ProcessExit += (_, _) => Dump();
                         global::System.Runtime.Loader.AssemblyLoadContext.Default.Unloading += _ => Dump();
                     }

                     public static bool C(int id, bool v)
                     {
                         if (v) global::System.Threading.Interlocked.Increment(ref t[id]);
                         else global::System.Threading.Interlocked.Increment(ref f[id]);
                         return v;
                     }

                     public static bool T(int id)
                     {
                         global::System.Threading.Interlocked.Increment(ref t[id]);
                         return true;
                     }

                     public static bool F(int id)
                     {
                         global::System.Threading.Interlocked.Increment(ref f[id]);
                         return false;
                     }

                     public static void Dump()
                     {
                         try
                         {
                             string dir = global::System.Environment.GetEnvironmentVariable("CONDCOV_DIR") ?? global::System.IO.Path.Combine(global::System.IO.Path.GetTempPath(), "condcov");
                             global::System.IO.Directory.CreateDirectory(dir);
                             var sb = new global::System.Text.StringBuilder();
                             for (int i = 0; i < t.Length; i++)
                                 if (t[i] != 0 || f[i] != 0) sb.Append(i).Append(',').Append(t[i]).Append(',').Append(f[i]).Append('\n');
                             // Dump nhiều lần (ProcessExit + Unloading) cùng pid: ghi đè bằng số liệu mới nhất.
                             global::System.IO.File.WriteAllText(global::System.IO.Path.Combine(dir, "hits-{{assembly}}-" + global::System.Environment.ProcessId + ".txt"), sb.ToString());
                         }
                         catch { }
                     }
                 }
                 """;
    }
}
